-- Offline deliverable. Install only after separate authorization into the isolated
-- research database. Additive: no historical function/table/row is replaced.
BEGIN;
SET LOCAL ROLE research_owner;
CREATE TABLE shadow_eval.a3_continuation_receipts(
 receipt_id text PRIMARY KEY,kind text NOT NULL CHECK(kind IN('continuation','source_review','capacity_risk')),
 study_id text NOT NULL REFERENCES shadow_eval.weekend_events(event_id),job_id text NOT NULL REFERENCES shadow_eval.weekend_events(event_id),
 body jsonb NOT NULL,body_hash text NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE UNIQUE INDEX continuation_director_message_once ON shadow_eval.a3_continuation_receipts(kind,(body->>'director_approval_sha256'))WHERE kind IN('continuation','capacity_risk');
ALTER TABLE shadow_eval.a3_continuation_receipts ENABLE ROW LEVEL SECURITY;
CREATE POLICY continuation_private_read ON shadow_eval.a3_continuation_receipts FOR SELECT TO shadow_reader,shadow_operator USING(true);
GRANT SELECT ON shadow_eval.a3_continuation_receipts TO shadow_reader,shadow_operator;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON shadow_eval.a3_continuation_receipts FOR EACH STATEMENT EXECUTE FUNCTION research.immutable();
CREATE TABLE shadow_eval.a3_continuation_attempts(
 study_id text PRIMARY KEY REFERENCES shadow_eval.weekend_events(event_id),
 approval_id text NOT NULL UNIQUE REFERENCES shadow_eval.a3_continuation_receipts(receipt_id),
 capacity_risk_id text UNIQUE REFERENCES shadow_eval.a3_continuation_receipts(receipt_id),
 job_id text NOT NULL REFERENCES shadow_eval.weekend_events(event_id),reservation_id text NOT NULL UNIQUE REFERENCES shadow_eval.weekend_events(event_id),
 request_hash text NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 scope_key text NOT NULL UNIQUE DEFAULT 'fiorentina-atalanta-1550169-20261029-v1' CHECK(scope_key='fiorentina-atalanta-1550169-20261029-v1'));
ALTER TABLE shadow_eval.a3_continuation_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY continuation_attempt_private_read ON shadow_eval.a3_continuation_attempts FOR SELECT TO shadow_reader,shadow_operator USING(true);
GRANT SELECT ON shadow_eval.a3_continuation_attempts TO shadow_reader,shadow_operator;
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON shadow_eval.a3_continuation_attempts FOR EACH STATEMENT EXECUTE FUNCTION research.immutable();
CREATE FUNCTION shadow_eval.a3_continuation_check(k text,jid text,b jsonb,at timestamptz)RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE j shadow_eval.weekend_events;p shadow_eval.weekend_events;s shadow_eval.weekend_events;r shadow_eval.a3_continuation_receipts;h jsonb;field text;
 common text[]:=ARRAY['study_id','job_id','fixture_id','kickoff_at_utc','issuance_date_utc','model','provider','backend','request_hash','request_body_hash','packet_hash','source_hash','prompt_hash','schema_hash','profile_hash','endpoint_contract_hash'];keys text[];
BEGIN
 keys:=ARRAY['version']||common||CASE k WHEN 'continuation' THEN ARRAY['source_review_id','source_review_body_hash','halt_anchors','one_attempt','max_new_micros','capacity_mode','director_approval_sha256','expires_at_utc'] WHEN 'source_review' THEN ARRAY['source_received_at_utc','availability_basis','settlement_basis','review_artifact_sha256'] WHEN 'capacity_risk' THEN ARRAY['continuation_id','continuation_body_hash','director_approval_sha256','review_artifact_sha256','capacity_status','complete_input_upper_tokens','input_bytes','provider_input_cap_tokens','context_tokens','physical_output_tokens','output_tokens','schema_contract_reviewed','output_contract_reviewed','expires_at_utc'] END;
 IF keys IS NULL OR jsonb_typeof(b)IS DISTINCT FROM 'object' OR octet_length(b::text)>16384 OR NOT(b ?& keys)OR EXISTS(SELECT FROM jsonb_object_keys(b)x WHERE x<>ALL(keys))THEN RAISE EXCEPTION 'closed continuation receipt required';END IF;
 FOREACH field IN ARRAY ARRAY['request_hash','request_body_hash','packet_hash','source_hash','prompt_hash','schema_hash','profile_hash','endpoint_contract_hash']LOOP
 IF jsonb_typeof(b->field)IS DISTINCT FROM 'string' OR coalesce(b->>field,'')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'continuation hash required';END IF;END LOOP;
 IF b->>'version' IS DISTINCT FROM (CASE k WHEN 'continuation' THEN 'a3-study-continuation-v1' WHEN 'source_review' THEN 'a3-continuation-source-review-v1' ELSE 'a3-scoped-capacity-risk-v1' END) OR b->>'fixture_id' IS DISTINCT FROM '1550169' OR b->>'kickoff_at_utc' IS DISTINCT FROM '2026-10-29T19:45:00Z' OR b->>'model' IS DISTINCT FROM 'openai/gpt-6-luna' OR b->>'provider' IS DISTINCT FROM 'OpenAI' OR b->>'backend' IS DISTINCT FROM 'openai' OR b->>'prompt_hash' IS DISTINCT FROM '19b28b55107630126de37f4b1fc1d52afc01aba1ebef9c9c802b289c2af406cf' OR b->>'schema_hash' IS DISTINCT FROM '7347a74b07cc5f0379db773dc4f174fe12d6c6ebf083fedf422379acaee5f500' THEN RAISE EXCEPTION 'fixed continuation identity or contract';END IF;
 SELECT * INTO STRICT j FROM shadow_eval.weekend_events WHERE event_id=jid AND kind='job';SELECT * INTO STRICT p FROM shadow_eval.weekend_events WHERE event_id=j.parent_id AND kind='packet';SELECT * INTO STRICT s FROM shadow_eval.weekend_events WHERE event_id=p.parent_id AND kind='study';
 IF b->>'study_id' IS DISTINCT FROM s.event_id OR b->>'job_id' IS DISTINCT FROM jid OR s.body->>'version' IS DISTINCT FROM 'a3-supervised-single-v1' OR s.body->'one_request' IS DISTINCT FROM 'true'::jsonb OR s.body->>'fixture_id' IS DISTINCT FROM '1550169' OR s.body->>'model' IS DISTINCT FROM 'openai/gpt-6-luna' OR s.body->>'provider' IS DISTINCT FROM 'OpenAI' OR s.body->>'source_hash' IS DISTINCT FROM b->>'source_hash' OR s.body->>'issuance_date_utc' IS DISTINCT FROM b->>'issuance_date_utc' OR j.body->>'fixture_id' IS DISTINCT FROM '1550169' OR j.body->>'kickoff_at_utc' IS DISTINCT FROM '2026-10-29T19:45:00Z' OR p.body->'targets' IS DISTINCT FROM '[1550169]'::jsonb OR(SELECT count(*)FROM jsonb_array_elements(p.body->'rows')x WHERE x->>'fxid'='1550169')<>1 OR(SELECT count(*)FROM jsonb_array_elements(p.body->'rows')x WHERE x->>'fxid'='1550169' AND x->>'home'='Fiorentina' AND x->>'away'='Atalanta' AND x->>'lid'='135' AND x->>'date'='2026-10-29' AND x->>'time'='19:45')<>1 THEN RAISE EXCEPTION 'continuation source study binding';END IF;
 IF coalesce(b->>'issuance_date_utc','')NOT IN('2026-10-28','2026-10-29')OR b->>'issuance_date_utc' IS DISTINCT FROM to_char(at AT TIME ZONE 'UTC','YYYY-MM-DD')OR p.body#>>'{collection,earliest_receipt_at_utc}' IS NULL OR p.body->>'source_read_at_utc' IS NULL OR(p.body#>>'{collection,earliest_receipt_at_utc}')::timestamptz>p.received_at OR(p.body->>'source_read_at_utc')::timestamptz>p.received_at OR at>=least((p.body#>>'{collection,earliest_receipt_at_utc}')::timestamptz+interval '15 minutes',(p.body->>'source_read_at_utc')::timestamptz+interval '15 minutes','2026-10-29T19:37:30Z'::timestamptz)THEN RAISE EXCEPTION 'continuation original source or date expired';END IF;
 IF k='source_review' THEN
  IF b->>'source_received_at_utc' IS NULL OR(b->>'source_received_at_utc')::timestamptz IS DISTINCT FROM p.received_at OR b->>'availability_basis' IS DISTINCT FROM 'current_pre_match_receipts' OR b->>'settlement_basis' IS DISTINCT FROM 'verified_regulation_90_plus_stoppage' OR coalesce(b->>'review_artifact_sha256','')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'independent source period review required';END IF;
 ELSE
  IF coalesce(b->>'director_approval_sha256','')!~'^[a-f0-9]{64}$' OR b->>'expires_at_utc' IS NULL OR(b->>'expires_at_utc')::timestamptz<=at OR(b->>'expires_at_utc')::timestamptz>least(at+interval '10 minutes',(p.body#>>'{collection,earliest_receipt_at_utc}')::timestamptz+interval '15 minutes',((b->>'issuance_date_utc')::date+1)::timestamp AT TIME ZONE 'UTC','2026-10-29T19:37:30Z'::timestamptz)THEN RAISE EXCEPTION 'scoped approval date or expiry';END IF;
 END IF;
 IF k='continuation' THEN
  SELECT * INTO STRICT r FROM shadow_eval.a3_continuation_receipts WHERE receipt_id=b->>'source_review_id' AND kind='source_review' AND job_id=jid AND body_hash=b->>'source_review_body_hash';
  FOREACH field IN ARRAY common LOOP IF r.body->field IS DISTINCT FROM b->field THEN RAISE EXCEPTION 'source review scope mismatch';END IF;END LOOP;
  IF b->'one_attempt' IS DISTINCT FROM 'true'::jsonb OR b->'max_new_micros' IS DISTINCT FROM '306000'::jsonb OR coalesce(b->>'capacity_mode','')NOT IN('verified_bound','capacity_risk')OR jsonb_typeof(b->'halt_anchors')IS DISTINCT FROM 'array' OR jsonb_array_length(b->'halt_anchors')NOT BETWEEN 1 AND 16 THEN RAISE EXCEPTION 'scoped continuation authority required';END IF;
  IF(SELECT count(DISTINCT x->>'event_id')FROM jsonb_array_elements(b->'halt_anchors')x)<>jsonb_array_length(b->'halt_anchors')OR(SELECT count(*)FROM shadow_eval.weekend_events WHERE kind='usage' AND body->'halt'='true'::jsonb)<>jsonb_array_length(b->'halt_anchors')THEN RAISE EXCEPTION 'historical halt inventory mismatch';END IF;
  FOR h IN SELECT value FROM jsonb_array_elements(b->'halt_anchors')LOOP
   IF jsonb_typeof(h)IS DISTINCT FROM 'object' OR NOT(h ?& ARRAY['event_id','event_body_hash'])OR EXISTS(SELECT FROM jsonb_object_keys(h)x WHERE x NOT IN('event_id','event_body_hash'))OR coalesce(h->>'event_body_hash','')!~'^[a-f0-9]{64}$' OR NOT EXISTS(SELECT FROM shadow_eval.weekend_events halt JOIN shadow_eval.weekend_events hold ON hold.event_id=halt.parent_id AND hold.kind='reservation' JOIN shadow_eval.weekend_events oldjob ON oldjob.event_id=hold.parent_id AND oldjob.kind='job' JOIN shadow_eval.weekend_events oldpacket ON oldpacket.event_id=oldjob.parent_id AND oldpacket.kind='packet' JOIN shadow_eval.weekend_events oldstudy ON oldstudy.event_id=oldpacket.parent_id AND oldstudy.kind='study' WHERE halt.event_id=h->>'event_id' AND halt.kind='usage' AND halt.body->'halt'='true'::jsonb AND halt.event_body_hash=h->>'event_body_hash' AND oldstudy.event_id<>s.event_id)THEN RAISE EXCEPTION 'halt anchor missing changed or same study';END IF;
  END LOOP;
 ELSIF k='capacity_risk' THEN
  SELECT * INTO STRICT r FROM shadow_eval.a3_continuation_receipts WHERE receipt_id=b->>'continuation_id' AND kind='continuation' AND job_id=jid AND body_hash=b->>'continuation_body_hash';
  FOREACH field IN ARRAY common LOOP IF r.body->field IS DISTINCT FROM b->field THEN RAISE EXCEPTION 'risk scope mismatch';END IF;END LOOP;
  IF r.body->>'capacity_mode' IS DISTINCT FROM 'capacity_risk' OR b->'complete_input_upper_tokens' IS DISTINCT FROM 'null'::jsonb OR b->>'capacity_status' IS DISTINCT FROM 'unverified' OR b->'provider_input_cap_tokens' IS DISTINCT FROM '922000'::jsonb OR b->'context_tokens' IS DISTINCT FROM '1050000'::jsonb OR b->'physical_output_tokens' IS DISTINCT FROM '128000'::jsonb OR b->'output_tokens' IS DISTINCT FROM '4096'::jsonb OR b->'schema_contract_reviewed' IS DISTINCT FROM 'true'::jsonb OR b->'output_contract_reviewed' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(b->'input_bytes')IS DISTINCT FROM 'number' OR coalesce(b->>'input_bytes','')!~'^[1-9][0-9]{0,6}$' OR(b->>'input_bytes')::bigint>1050000 OR coalesce(b->>'review_artifact_sha256','')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'scoped capacity risk must remain unverified';END IF;
 END IF;
END $$;
CREATE FUNCTION shadow_eval.a3_continuation_record(k text,id text,jid text,b jsonb)RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
BEGIN
 IF id !~'^[A-Za-z0-9:._-]{1,128}$' THEN RAISE EXCEPTION 'invalid continuation receipt identifier';END IF;
 PERFORM 1 FROM research.control FOR UPDATE;PERFORM shadow_eval.a3_continuation_check(k,jid,b,clock_timestamp());PERFORM research.check_budget(octet_length(b::text)*4+65536);
 INSERT INTO shadow_eval.a3_continuation_receipts VALUES(id,k,b->>'study_id',jid,b,encode(public.digest(b::text,'sha256'),'hex'),clock_timestamp());RETURN id;
END $$;
CREATE FUNCTION shadow_eval.a3_continuation_reserve(aid text,rid text,jid text,b jsonb)RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE a shadow_eval.a3_operator_receipts;c shadow_eval.a3_continuation_receipts;r shadow_eval.a3_continuation_receipts;proof shadow_eval.a3_operator_receipts;p shadow_eval.weekend_events;j shadow_eval.weekend_events;s shadow_eval.weekend_events;deadline timestamptz;hard timestamptz;at timestamptz;riskid text;
BEGIN
 PERFORM 1 FROM research.control FOR UPDATE;at:=clock_timestamp();
 SELECT * INTO STRICT a FROM shadow_eval.a3_operator_receipts WHERE receipt_id=aid AND kind='authorization' AND job_id=jid;
 SELECT * INTO STRICT c FROM shadow_eval.a3_continuation_receipts WHERE receipt_id=b->>'continuation_id' AND kind='continuation' AND job_id=jid;
 SELECT * INTO STRICT j FROM shadow_eval.weekend_events WHERE event_id=jid AND kind='job';SELECT * INTO STRICT p FROM shadow_eval.weekend_events WHERE event_id=j.parent_id AND kind='packet';SELECT * INTO STRICT s FROM shadow_eval.weekend_events WHERE event_id=p.parent_id AND kind='study';
 PERFORM shadow_eval.a3_continuation_check('continuation',jid,c.body,at);
 IF EXISTS(SELECT FROM shadow_eval.a3_single_attempts WHERE study_id=s.event_id)OR EXISTS(SELECT FROM shadow_eval.a3_continuation_attempts)OR EXISTS(SELECT FROM shadow_eval.weekend_events hold JOIN shadow_eval.weekend_events job ON job.event_id=hold.parent_id JOIN shadow_eval.weekend_events packet ON packet.event_id=job.parent_id WHERE hold.kind='reservation' AND packet.parent_id=s.event_id)THEN RAISE EXCEPTION 'continuation study already attempted';END IF;
 IF b->>'continuation_body_hash' IS DISTINCT FROM c.body_hash OR a.body->>'continuation_id' IS DISTINCT FROM c.receipt_id OR a.body->>'continuation_body_hash' IS DISTINCT FROM c.body_hash OR b->>'source_review_id' IS DISTINCT FROM c.body->>'source_review_id' OR b->>'source_review_body_hash' IS DISTINCT FROM c.body->>'source_review_body_hash' OR b->>'request_hash' IS DISTINCT FROM c.body->>'request_hash' OR a.body->>'request_hash' IS DISTINCT FROM c.body->>'request_hash' OR b->>'request_body_hash' IS DISTINCT FROM c.body->>'request_body_hash' OR b->>'packet_hash' IS DISTINCT FROM c.body->>'packet_hash' OR a.body->>'packet_hash' IS DISTINCT FROM c.body->>'packet_hash' OR b->'reserved_micros' IS DISTINCT FROM '306000'::jsonb OR a.body->'max_new_micros' IS DISTINCT FROM '306000'::jsonb OR a.body->>'fixture_id' IS DISTINCT FROM '1550169' OR a.body->>'issuance_date_utc' IS DISTINCT FROM c.body->>'issuance_date_utc' OR a.body->>'model' IS DISTINCT FROM 'openai/gpt-6-luna' OR a.body->>'provider' IS DISTINCT FROM 'OpenAI' OR b ? 'capacity_exception_id' THEN RAISE EXCEPTION 'atomic continuation authorization scope';END IF;
 SELECT * INTO STRICT r FROM shadow_eval.a3_continuation_receipts WHERE receipt_id=c.body->>'source_review_id' AND kind='source_review' AND job_id=jid AND body_hash=c.body->>'source_review_body_hash';PERFORM shadow_eval.a3_continuation_check('source_review',jid,r.body,at);
 IF jsonb_typeof(b->'canonical_request_body')IS DISTINCT FROM 'string' OR octet_length(b->>'canonical_request_body')>1050000 OR encode(public.digest(b->>'canonical_request_body','sha256'),'hex')IS DISTINCT FROM c.body->>'request_body_hash' OR(b->>'canonical_request_body')::jsonb IS DISTINCT FROM b#>'{request,body}' OR b#>>'{profile,profile_hash}' IS DISTINCT FROM c.body->>'profile_hash' OR b#>>'{request,body,model}' IS DISTINCT FROM 'openai/gpt-6-luna' OR b#>'{request,body,max_tokens}' IS DISTINCT FROM '4096'::jsonb OR b#>'{request,body,stream}' IS DISTINCT FROM 'false'::jsonb OR b#>'{request,body,tools}' IS DISTINCT FROM '[]'::jsonb OR b#>'{request,body,plugins}' IS DISTINCT FROM '[]'::jsonb OR b#>>'{request,body,tool_choice}' IS DISTINCT FROM 'none' OR b#>'{request,body,provider,only}' IS DISTINCT FROM '["openai"]'::jsonb OR b#>'{request,body,provider,allow_fallbacks}' IS DISTINCT FROM 'false'::jsonb OR b#>'{request,body,provider,require_parameters}' IS DISTINCT FROM 'true'::jsonb OR b#>'{request,body,provider,max_price}' IS DISTINCT FROM '{"prompt":0.2,"completion":0.75}'::jsonb THEN RAISE EXCEPTION 'exact continuation request body or provider mismatch';END IF;
 IF c.body->>'capacity_mode'='capacity_risk' THEN
  SELECT * INTO STRICT r FROM shadow_eval.a3_continuation_receipts WHERE receipt_id=b->>'scoped_capacity_id' AND kind='capacity_risk' AND job_id=jid;PERFORM shadow_eval.a3_continuation_check('capacity_risk',jid,r.body,at);riskid:=r.receipt_id;
  IF b ? 'readiness_id' OR a.body->>'scoped_capacity_id' IS DISTINCT FROM r.receipt_id OR a.body->>'scoped_capacity_body_hash' IS DISTINCT FROM r.body_hash OR b->>'scoped_capacity_body_hash' IS DISTINCT FROM r.body_hash OR b->>'capacity_status' IS DISTINCT FROM 'unverified' OR a.body->>'capacity_status' IS DISTINCT FROM 'unverified' OR b->'complete_input_upper_tokens' IS DISTINCT FROM 'null'::jsonb OR(b->>'canonical_request_body')IS NULL OR(r.body->>'input_bytes')::bigint<>octet_length(b->>'canonical_request_body')THEN RAISE EXCEPTION 'atomic scoped capacity mismatch';END IF;
 ELSE
  IF b ? 'scoped_capacity_id' OR a.body ? 'scoped_capacity_id' THEN RAISE EXCEPTION 'risk not authorized by continuation';END IF;
  SELECT * INTO STRICT proof FROM shadow_eval.a3_operator_receipts WHERE receipt_id=b->>'readiness_id' AND kind='readiness' AND job_id=jid;
  IF proof.body->>'request_hash' IS DISTINCT FROM c.body->>'request_hash' OR proof.body->>'profile_hash' IS DISTINCT FROM c.body->>'profile_hash' OR proof.body->>'schema_hash' IS DISTINCT FROM c.body->>'schema_hash' OR(proof.body->>'complete_input_upper_tokens')::bigint>922000 OR(proof.body->>'complete_input_upper_tokens')::bigint+128000>1050000 THEN RAISE EXCEPTION 'reviewed continuation capacity required';END IF;
 END IF;
 IF a.received_at<c.received_at OR(riskid IS NOT NULL AND a.received_at<r.received_at)OR a.received_at>at OR b->>'gate_deadline_utc' IS NULL OR a.body#>>'{byok,recorded_at_utc}' IS NULL OR(a.body#>>'{byok,recorded_at_utc}')::timestamptz>at THEN RAISE EXCEPTION 'continuation original authorization clocks absent';END IF;
 hard:=least((c.body->>'expires_at_utc')::timestamptz,c.received_at+interval '10 minutes',(a.body->>'expires_at_utc')::timestamptz,a.received_at+interval '10 minutes',(a.body#>>'{byok,recorded_at_utc}')::timestamptz+interval '10 minutes',(p.body#>>'{collection,earliest_receipt_at_utc}')::timestamptz+interval '15 minutes',(p.body->>'source_read_at_utc')::timestamptz+interval '15 minutes','2026-10-29T19:37:30Z'::timestamptz,((c.body->>'issuance_date_utc')::date+1)::timestamp AT TIME ZONE 'UTC',CASE WHEN riskid IS NOT NULL THEN least((r.body->>'expires_at_utc')::timestamptz,r.received_at+interval '10 minutes')ELSE 'infinity'::timestamptz END);
 IF clock_timestamp()+interval '6 minutes'>=hard THEN RAISE EXCEPTION 'insufficient continuation pre HTTP window';END IF;
 deadline:=least(hard,(b->>'gate_deadline_utc')::timestamptz);IF clock_timestamp()>=deadline THEN RAISE EXCEPTION 'continuation effective deadline expired';END IF;
 -- Reuse the existing atomic path where possible; risk uses the same financial
 -- writer/lock and both paths consume the original per-study latch as well.
 IF riskid IS NULL THEN PERFORM shadow_eval.a3_single_reserve(aid,rid,jid,b);
 ELSE
  PERFORM shadow_eval.weekend_append('reservation',rid,jid,b||'{"requires_confirmation":true}'::jsonb);PERFORM shadow_eval.weekend_append('confirmation',rid||':commit',rid,'{"status":"accepted"}'::jsonb);INSERT INTO shadow_eval.a3_single_attempts VALUES(s.event_id,jid,rid,b->>'request_hash',clock_timestamp());
 END IF;
 INSERT INTO shadow_eval.a3_continuation_attempts(study_id,approval_id,capacity_risk_id,job_id,reservation_id,request_hash,received_at)VALUES(s.event_id,c.receipt_id,riskid,jid,rid,b->>'request_hash',clock_timestamp());
 IF clock_timestamp()>=deadline THEN RAISE EXCEPTION 'continuation deadline crossed before commit';END IF;RETURN rid;
END $$;
REVOKE ALL ON FUNCTION shadow_eval.a3_continuation_check(text,text,jsonb,timestamptz),shadow_eval.a3_continuation_record(text,text,text,jsonb),shadow_eval.a3_continuation_reserve(text,text,text,jsonb)FROM PUBLIC,anon,authenticated,shadow_runner,shadow_operator;
GRANT EXECUTE ON FUNCTION shadow_eval.a3_continuation_record(text,text,text,jsonb),shadow_eval.a3_continuation_reserve(text,text,text,jsonb)TO shadow_operator;
COMMIT;
